CREATE TABLE `channels`
(`channel_id` BIGINT,
`channel_name` VARCHAR(1023),
`channel_type` VARCHAR(1023));
CREATE TABLE `drivers`
(`driver_id` BIGINT,
`driver_modal` VARCHAR(1023),
`driver_type` VARCHAR(1023));
CREATE TABLE `hubs`
(`hub_id` BIGINT,
`hub_name` VARCHAR(1023),
`hub_city` VARCHAR(1023),
`hub_state` VARCHAR(1023),
`hub_latitude` DOUBLE,
`hub_longitude` DOUBLE);
CREATE TABLE `stores`
(`store_id` BIGINT,
`hub_id` BIGINT,
`store_name` VARCHAR(1023),
`store_segment` VARCHAR(1023),
`store_plan_price` DOUBLE,
`store_latitude` DOUBLE,
`store_longitude` DOUBLE);
CREATE TABLE `orders`
(`order_id` BIGINT,
`store_id` BIGINT,
`channel_id` BIGINT,
`payment_order_id` BIGINT,
`delivery_order_id` BIGINT,
`order_status` VARCHAR(1023),
`order_amount` DOUBLE,
`order_delivery_fee` DOUBLE,
`order_delivery_cost` DOUBLE,
`order_created_hour` BIGINT,
`order_created_minute` BIGINT,
`order_created_day` BIGINT,
`order_created_month` BIGINT,
`order_created_year` BIGINT,
`order_moment_created` DATETIME,
`order_moment_accepted` DATETIME,
`order_moment_ready` DATETIME,
`order_moment_collected` DATETIME,
`order_moment_in_expedition` DATETIME,
`order_moment_delivering` DATETIME,
`order_moment_delivered` DATETIME,
`order_moment_finished` DATETIME,
`order_metric_collected_time` DOUBLE,
`order_metric_paused_time` DOUBLE,
`order_metric_production_time` DOUBLE,
`order_metric_walking_time` DOUBLE,
`order_metric_expediton_speed_time` DOUBLE,
`order_metric_transit_time` DOUBLE,
`order_metric_cycle_time` DOUBLE);
CREATE TABLE `deliveries`
(`delivery_id` BIGINT,
`delivery_order_id` BIGINT,
`driver_id` BIGINT,
`delivery_distance_meters` DOUBLE,
`delivery_status` VARCHAR(1023));
CREATE TABLE `payments`
(`payment_id` BIGINT,
`payment_order_id` BIGINT,
`payment_amount` DOUBLE,
`payment_fee` DOUBLE,
`payment_method` VARCHAR(1023),
`payment_status` VARCHAR(1023));
